73	UUID BackupsWorker::startMakingBackup(const ASTPtr & query, const ContextPtr & context)
74	{
75	    auto backup_query = std::static_pointer_cast<ASTBackupQuery>(query->clone());
76	    auto backup_settings = BackupSettings::fromBackupQuery(*backup_query);
77	    auto backup_info = BackupInfo::fromAST(*backup_query->backup_name);
78	    bool on_cluster = !backup_query->cluster.empty();
79	
80	    if (!backup_settings.backup_uuid)
81	        backup_settings.backup_uuid = UUIDHelpers::generateV4();
82	    UUID backup_uuid = *backup_settings.backup_uuid;
83	
84	    /// Prepare context to use.
85	    ContextPtr context_in_use = context;
86	    ContextMutablePtr mutable_context;
87	    if (on_cluster || backup_settings.async)
88	    {
89	        /// For ON CLUSTER queries we will need to change some settings.
90	        /// For ASYNC queries we have to clone the context anyway.
91	        context_in_use = mutable_context = Context::createCopy(context);
92	    }
93	
94	    addInfo(backup_uuid, backup_info.toString(), BackupStatus::MAKING_BACKUP, backup_settings.internal);
95	
96	    auto job = [this,
97	                backup_uuid,
98	                backup_query,
99	                backup_settings,
100	                backup_info,
101	                on_cluster,
102	                context_in_use,
103	                mutable_context](bool async) mutable
104	    {
105	        std::optional<CurrentThread::QueryScope> query_scope;
106	        std::shared_ptr<IBackupCoordination> backup_coordination;
107	        SCOPE_EXIT_SAFE(if (backup_coordination && !backup_settings.internal) backup_coordination->drop(););
108	
109	        try
110	        {
111	            if (async)
112	            {
113	                query_scope.emplace(mutable_context);
114	                setThreadName("BackupWorker");
115	            }
116	
117	            /// Checks access rights if this is not ON CLUSTER query.
118	            /// (If this is ON CLUSTER query executeDDLQueryOnCluster() will check access rights later.)
119	            auto required_access = getRequiredAccessToBackup(backup_query->elements);
120	            if (!on_cluster)
121	                context_in_use->checkAccess(required_access);
122	
123	            ClusterPtr cluster;
124	            if (on_cluster)
125	            {
126	                backup_query->cluster = context_in_use->getMacros()->expand(backup_query->cluster);
127	                cluster = context_in_use->getCluster(backup_query->cluster);
128	                backup_settings.cluster_host_ids = cluster->getHostIDs();
129	                if (backup_settings.coordination_zk_path.empty())
130	                {
131	                    String root_zk_path = context_in_use->getConfigRef().getString("backups.zookeeper_path", "/clickhouse/backups");
132	                    backup_settings.coordination_zk_path = root_zk_path + "/backup-" + toString(backup_uuid);
133	                }
134	            }
135	
136	            /// Make a backup coordination.
137	            if (!backup_settings.coordination_zk_path.empty())
138	            {
139	                backup_coordination = std::make_shared<BackupCoordinationRemote>(
140	                    backup_settings.coordination_zk_path,
141	                    [global_context = context_in_use->getGlobalContext()] { return global_context->getZooKeeper(); });
142	            }
143	            else
144	            {
145	                backup_coordination = std::make_shared<BackupCoordinationLocal>();
146	            }
147	
148	            /// Opens a backup for writing.
149	            BackupFactory::CreateParams backup_create_params;
150	            backup_create_params.open_mode = IBackup::OpenMode::WRITE;
151	            backup_create_params.context = context_in_use;
152	            backup_create_params.backup_info = backup_info;
153	            backup_create_params.base_backup_info = backup_settings.base_backup_info;
154	            backup_create_params.compression_method = backup_settings.compression_method;
155	            backup_create_params.compression_level = backup_settings.compression_level;
156	            backup_create_params.password = backup_settings.password;
157	            backup_create_params.is_internal_backup = backup_settings.internal;
158	            backup_create_params.backup_coordination = backup_coordination;
159	            backup_create_params.backup_uuid = backup_uuid;
160	            BackupMutablePtr backup = BackupFactory::instance().createBackup(backup_create_params);
161	
162	            /// Write the backup.
163	            if (on_cluster)
164	            {
165	                DDLQueryOnClusterParams params;
166	                params.cluster = cluster;
167	                params.only_shard_num = backup_settings.shard_num;
168	                params.only_replica_num = backup_settings.replica_num;
169	                params.access_to_check = required_access;
170	                backup_settings.copySettingsToQuery(*backup_query);
171	
172	                // executeDDLQueryOnCluster() will return without waiting for completion
173	                mutable_context->setSetting("distributed_ddl_task_timeout", Field{0});
174	                mutable_context->setSetting("distributed_ddl_output_mode", Field{"none"});
175	                executeDDLQueryOnCluster(backup_query, mutable_context, params);
176	
177	                /// Wait until all the hosts have written their backup entries.
178	                auto all_hosts = BackupSettings::Util::filterHostIDs(
179	                    backup_settings.cluster_host_ids, backup_settings.shard_num, backup_settings.replica_num);
180	                backup_coordination->waitStatus(all_hosts, kCompletedCoordinationStatus);
181	            }
182	            else
183	            {
184	                backup_query->setCurrentDatabase(context_in_use->getCurrentDatabase());
185	
186	                /// Prepare backup entries.
187	                BackupEntries backup_entries;
188	                {
189	                    BackupEntriesCollector backup_entries_collector{backup_query->elements, backup_settings, backup_coordination, context_in_use};
190	                    backup_entries = backup_entries_collector.run();
191	                }
192	
193	                /// Write the backup entries to the backup.
194	                writeBackupEntries(backup, std::move(backup_entries), backups_thread_pool);
195	
196	                /// We have written our backup entries, we need to tell other hosts (they could be waiting for it).
197	                backup_coordination->setStatus(backup_settings.host_id, kCompletedCoordinationStatus, "");
198	            }
199	
200	            /// Finalize backup (write its metadata).
201	            if (!backup_settings.internal)
202	                backup->finalizeWriting();
203	
204	            /// Close the backup.
205	            backup.reset();
206	
207	            setStatus(backup_uuid, BackupStatus::BACKUP_COMPLETE);
208	        }
209	        catch (...)
210	        {
211	            /// Something bad happened, the backup has not built.
212	            setStatus(backup_uuid, BackupStatus::FAILED_TO_BACKUP);
213	            sendErrorToCoordination(backup_coordination, backup_settings.host_id);
214	            if (!async)
215	                throw;
216	        }
217	    };
218	
219	    if (backup_settings.async)
220	        backups_thread_pool.scheduleOrThrowOnError([job]() mutable { job(true); });
221	    else
222	        job(false);
223	
224	    return backup_uuid;
225	}
