228	UUID BackupsWorker::startRestoring(const ASTPtr & query, ContextMutablePtr context)
229	{
230	    UUID restore_uuid = UUIDHelpers::generateV4();
231	    auto restore_query = std::static_pointer_cast<ASTBackupQuery>(query->clone());
232	    auto restore_settings = RestoreSettings::fromRestoreQuery(*restore_query);
233	    auto backup_info = BackupInfo::fromAST(*restore_query->backup_name);
234	    bool on_cluster = !restore_query->cluster.empty();
235	
236	    /// Prepare context to use.
237	    ContextMutablePtr context_in_use = context;
238	    if (restore_settings.async || on_cluster)
239	    {
240	        /// For ON CLUSTER queries we will need to change some settings.
241	        /// For ASYNC queries we have to clone the context anyway.
242	        context_in_use = Context::createCopy(context);
243	    }
244	
245	    addInfo(restore_uuid, backup_info.toString(), BackupStatus::RESTORING, restore_settings.internal);
246	
247	    auto job = [this,
248	                restore_uuid,
249	                restore_query,
250	                restore_settings,
251	                backup_info,
252	                on_cluster,
253	                context_in_use](bool async) mutable
254	    {
255	        std::optional<CurrentThread::QueryScope> query_scope;
256	        std::shared_ptr<IRestoreCoordination> restore_coordination;
257	        SCOPE_EXIT_SAFE(if (restore_coordination && !restore_settings.internal) restore_coordination->drop(););
258	
259	        try
260	        {
261	            if (async)
262	            {
263	                query_scope.emplace(context_in_use);
264	                setThreadName("RestoreWorker");
265	            }
266	
267	            /// Open the backup for reading.
268	            BackupFactory::CreateParams backup_open_params;
269	            backup_open_params.open_mode = IBackup::OpenMode::READ;
270	            backup_open_params.context = context_in_use;
271	            backup_open_params.backup_info = backup_info;
272	            backup_open_params.base_backup_info = restore_settings.base_backup_info;
273	            backup_open_params.password = restore_settings.password;
274	            BackupPtr backup = BackupFactory::instance().createBackup(backup_open_params);
275	
276	            String current_database = context_in_use->getCurrentDatabase();
277	
278	            /// Checks access rights if this is ON CLUSTER query.
279	            /// (If this isn't ON CLUSTER query RestorerFromBackup will check access rights later.)
280	            ClusterPtr cluster;
281	            if (on_cluster)
282	            {
283	                restore_query->cluster = context_in_use->getMacros()->expand(restore_query->cluster);
284	                cluster = context_in_use->getCluster(restore_query->cluster);
285	                restore_settings.cluster_host_ids = cluster->getHostIDs();
286	
287	                /// We cannot just use access checking provided by the function executeDDLQueryOnCluster(): it would be incorrect
288	                /// because different replicas can contain different set of tables and so the required access rights can differ too.
289	                /// So the right way is pass through the entire cluster and check access for each host.
290	                auto addresses = cluster->filterAddressesByShardOrReplica(restore_settings.shard_num, restore_settings.replica_num);
291	                for (const auto * address : addresses)
292	                {
293	                    restore_settings.host_id = address->toString();
294	                    auto restore_elements = restore_query->elements;
295	                    String addr_database = address->default_database.empty() ? current_database : address->default_database;
296	                    for (auto & element : restore_elements)
297	                        element.setCurrentDatabase(addr_database);
298	                    RestorerFromBackup dummy_restorer{restore_elements, restore_settings, nullptr, backup, context_in_use};
299	                    dummy_restorer.run(RestorerFromBackup::CHECK_ACCESS_ONLY);
300	                }
301	            }
302	
303	            /// Make a restore coordination.
304	            if (on_cluster && restore_settings.coordination_zk_path.empty())
305	            {
306	                String root_zk_path = context_in_use->getConfigRef().getString("backups.zookeeper_path", "/clickhouse/backups");
307	                restore_settings.coordination_zk_path = root_zk_path + "/restore-" + toString(restore_uuid);
308	            }
309	
310	            if (!restore_settings.coordination_zk_path.empty())
311	            {
312	                restore_coordination = std::make_shared<RestoreCoordinationRemote>(
313	                    restore_settings.coordination_zk_path,
314	                    [global_context = context_in_use->getGlobalContext()] { return global_context->getZooKeeper(); });
315	            }
316	            else
317	            {
318	                restore_coordination = std::make_shared<RestoreCoordinationLocal>();
319	            }
320	
321	            /// Do RESTORE.
322	            if (on_cluster)
323	            {
324	
325	                DDLQueryOnClusterParams params;
326	                params.cluster = cluster;
327	                params.only_shard_num = restore_settings.shard_num;
328	                params.only_replica_num = restore_settings.replica_num;
329	                restore_settings.copySettingsToQuery(*restore_query);
330	
331	                // executeDDLQueryOnCluster() will return without waiting for completion
332	                context_in_use->setSetting("distributed_ddl_task_timeout", Field{0});
333	                context_in_use->setSetting("distributed_ddl_output_mode", Field{"none"});
334	
335	                executeDDLQueryOnCluster(restore_query, context_in_use, params);
336	
337	                /// Wait until all the hosts have written their backup entries.
338	                auto all_hosts = BackupSettings::Util::filterHostIDs(
339	                    restore_settings.cluster_host_ids, restore_settings.shard_num, restore_settings.replica_num);
340	                restore_coordination->waitStatus(all_hosts, kCompletedCoordinationStatus);
341	            }
342	            else
343	            {
344	                restore_query->setCurrentDatabase(current_database);
345	
346	                /// Restore metadata and prepare data restoring tasks.
347	                DataRestoreTasks data_restore_tasks;
348	                {
349	                    RestorerFromBackup restorer{restore_query->elements, restore_settings, restore_coordination,
350	                                                backup, context_in_use};
351	                    data_restore_tasks = restorer.run(RestorerFromBackup::RESTORE);
352	                }
353	
354	                /// Execute the data restoring tasks.
355	                restoreTablesData(std::move(data_restore_tasks), restores_thread_pool);
356	
357	                /// We have restored everything, we need to tell other hosts (they could be waiting for it).
358	                restore_coordination->setStatus(restore_settings.host_id, kCompletedCoordinationStatus, "");
359	            }
360	
361	            setStatus(restore_uuid, BackupStatus::RESTORED);
362	        }
363	        catch (...)
364	        {
365	            /// Something bad happened, the backup has not built.
366	            setStatus(restore_uuid, BackupStatus::FAILED_TO_RESTORE);
367	            sendErrorToCoordination(restore_coordination, restore_settings.host_id);
368	            if (!async)
369	                throw;
370	        }
371	    };
372	
373	    if (restore_settings.async)
374	        backups_thread_pool.scheduleOrThrowOnError([job]() mutable { job(true); });
375	    else
376	        job(false);
377	
378	    return restore_uuid;
379	}
