382	void BackupsWorker::addInfo(const UUID & uuid, const String & backup_name, BackupStatus status, bool internal)
383	{
384	    Info info;
385	    info.uuid = uuid;
386	    info.backup_name = backup_name;
387	    info.status = status;
388	    info.status_changed_time = time(nullptr);
