394	void BackupsWorker::setStatus(const UUID & uuid, BackupStatus status)
395	{
396	    std::lock_guard lock{infos_mutex};
397	    auto & info = infos.at(uuid);
398	    info.status = status;
399	    info.status_changed_time = time(nullptr);
400	
401	    if (status == BackupStatus::BACKUP_COMPLETE)
402	    {
403	        LOG_INFO(log, "{} {} was created successfully", (info.internal ? "Internal backup" : "Backup"), info.backup_name);
404	    }
405	    else if (status == BackupStatus::RESTORED)
406	    {
407	        LOG_INFO(log, "Restored from {} {} successfully", (info.internal ? "internal backup" : "backup"), info.backup_name);
408	    }
409	    else if ((status == BackupStatus::FAILED_TO_BACKUP) || (status == BackupStatus::FAILED_TO_RESTORE))
410	    {
411	        String start_of_message;
412	        if (status == BackupStatus::FAILED_TO_BACKUP)
413	            start_of_message = fmt::format("Failed to create {} {}", (info.internal ? "internal backup" : "backup"), info.backup_name);
414	        else
415	            start_of_message = fmt::format("Failed to restore from {} {}", (info.internal ? "internal backup" : "backup"), info.backup_name);
416	        tryLogCurrentException(log, start_of_message);
417	
418	        info.error_message = getCurrentExceptionMessage(false);
419	        info.exception = std::current_exception();
420	    }
421	}
