424	void BackupsWorker::wait(const UUID & backup_or_restore_uuid, bool rethrow_exception)
425	{
426	    std::unique_lock lock{infos_mutex};
427	    status_changed.wait(lock, [&]
428	    {
429	        auto it = infos.find(backup_or_restore_uuid);
430	        if (it == infos.end())
431	            throw Exception(ErrorCodes::LOGICAL_ERROR, "BackupsWorker: Unknown UUID {}", toString(backup_or_restore_uuid));
432	        const auto & info = it->second;
433	        auto current_status = info.status;
434	        if (rethrow_exception && ((current_status == BackupStatus::FAILED_TO_BACKUP) || (current_status == BackupStatus::FAILED_TO_RESTORE)))
435	            std::rethrow_exception(info.exception);
436	        return (current_status == BackupStatus::BACKUP_COMPLETE) || (current_status == BackupStatus::RESTORED);
437	    });
438	}
