458	void BackupsWorker::shutdown()
459	{
460	    size_t num_active_backups = backups_thread_pool.active();
461	    size_t num_active_restores = restores_thread_pool.active();
462	    if (!num_active_backups && !num_active_restores)
463	        return;
464	    LOG_INFO(log, "Waiting for {} backup and {} restore tasks to be finished", num_active_backups, num_active_restores);
465	    backups_thread_pool.wait();
466	    restores_thread_pool.wait();
467	    LOG_INFO(log, "All backup and restore tasks have finished");
468	}
